%
% map = loadMapdt(2,1)
load extractedEfromRed.mat
%%
ldos_conductance_Together__Constants
%%
iCr = 2 %[output:2f794488]
icas = [1 2 1 2]; ica = icas(iCr);
ibas = [1 1 2 2]; iba = ibas(iCr);
%%
vFcs = vFcss(mod(iCr-1,2)+1,:);
%%
V = map.vm*1000;
xrng = (0:r) + xyT{iCr,1}(1);
yrng = (0:r) + xyT{iCr,1}(2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
gfcs = squeeze(mean(mean(Gfcs)))*10;%multiplication is no mean. just reduce the size of ticks
area(V,gfcs,FaceColor=[0.231 0.667 0.196]) %[control:colorPicker:7128]{"position":[23,42]} %[output:7272dfcc]
xlim([-760 760]); %[output:7272dfcc]
ylim([0 1.1]) %[output:7272dfcc]
s.Avg.Clipping ="off";
xline(vFcs,'w:',LineWidth=2) %[output:7272dfcc]
hold on %[output:7272dfcc]
plot(V,gfcs,'k',LineWidth=2.5) %[output:7272dfcc]
hold off %[output:7272dfcc]
xlabel(labeler('E','meV')); %[output:7272dfcc]
ylabel(labeler('LDOS','a.u')); %[output:7272dfcc]
xline(epos{ica},'r',LineWidth=3)
%%
